export interface AgentIdentity {
  edPublicKey: Uint8Array;
  edPrivateKey: Uint8Array;
  fingerprint: string;
  displayName?: string;
}

export interface PeerInfo {
  publicKey: Uint8Array;
  fingerprint: string;
  displayName?: string;
  trusted: boolean;
  lastSeen?: number;
}

export interface GroupInfo {
  groupId: Uint8Array;
  name: string;
  role: string;
  createdAt: number;
  memberCount: number;
}

export interface IdentityHandshake {
  type: 'IdentityHandshake';
  edPublicKey: Uint8Array;
  signature: Uint8Array;
  timestamp: number;
  displayName?: string;
}

export interface GroupSync {
  type: 'GroupSync';
  groups: Array<{ groupId: Uint8Array; name: string }>;
}

export interface SenderKeyDistribution {
  type: 'SenderKeyDistribution';
  groupId: Uint8Array;
  senderPublicKey: Uint8Array;
  chainKey: Uint8Array;
  chainIndex: number;
}

export interface GroupMessage {
  type: 'GroupMessage';
  groupId: Uint8Array;
  ciphertext: Uint8Array;
  signature: Uint8Array;
  chainIndex: number;
  messageId?: string;
  timestamp?: number;
}

export interface DirectMessage {
  type: 'DirectMessage';
  senderPublicKey: Uint8Array;
  recipientPublicKey: Uint8Array;
  ciphertext: Uint8Array;
  signature: Uint8Array;
  messageId?: string;
  timestamp?: number;
}

export interface GroupManagement {
  type: 'GroupManagement';
  action: 'invite' | 'kick' | 'promote' | 'demote';
  groupId: Uint8Array;
  targetPublicKey?: Uint8Array;
  senderPublicKey: Uint8Array;
  groupName?: string;
  timestamp: number;
}

export interface TTYARequest {
  type: 'TTYARequest';
  [key: string]: unknown;
}

export interface TTYAResponse {
  type: 'TTYAResponse';
  [key: string]: unknown;
}

export interface Ack {
  type: 'Ack';
  messageId: string;
  [key: string]: unknown;
}

export type ProtocolMessage =
  | IdentityHandshake
  | GroupSync
  | SenderKeyDistribution
  | GroupMessage
  | DirectMessage
  | GroupManagement
  | TTYARequest
  | TTYAResponse
  | Ack
  | { type: string; [key: string]: unknown };

export function generateIdentity(): { publicKey: Uint8Array; privateKey: Uint8Array };
export function fingerprintFromPublicKey(publicKey: Uint8Array): string;
export function encrypt(plaintext: Uint8Array, key: Uint8Array, nonce: Uint8Array): Uint8Array;
export function decrypt(ciphertext: Uint8Array, key: Uint8Array, nonce: Uint8Array): Uint8Array;
export function deriveKey(ikm: Uint8Array, info: string, salt: string, length: number): Uint8Array;
export function advanceChain(chainKey: Uint8Array): { nextChainKey: Uint8Array; messageKey: Uint8Array };
export function sign(data: Uint8Array, privateKey: Uint8Array): Uint8Array;
export function verify(signature: Uint8Array, data: Uint8Array, publicKey: Uint8Array): boolean;
export function encodeMessage(message: ProtocolMessage): Uint8Array;
export function decodeMessage(data: Uint8Array): ProtocolMessage;
export function frameMessage(data: Uint8Array): Uint8Array;
export function parseFrame(data: Uint8Array): Uint8Array;

export interface SenderKeyState {
  chainKey: Uint8Array;
  chainIndex: number;
}

export declare const SenderKeys: {
  generate(): SenderKeyState;
  encrypt(plaintext: Uint8Array, state: SenderKeyState): { ciphertext: Uint8Array; nextState: SenderKeyState };
  decrypt(ciphertext: Uint8Array, state: SenderKeyState, chainIndex: number): { plaintext: Uint8Array; nextState: SenderKeyState };
  createDistribution(state: SenderKeyState, senderPublicKey: Uint8Array, groupId: Uint8Array): {
    chainKey: Uint8Array;
    chainIndex: number;
    senderPublicKey: Uint8Array;
    groupId: Uint8Array;
  };
};

export declare const DoubleRatchet: {
  initSender(sharedSecret: Uint8Array, remotePublicKey: Uint8Array): unknown;
  initReceiver(sharedSecret: Uint8Array, keyPair: { publicKey: Uint8Array; privateKey: Uint8Array }): unknown;
  encrypt(state: unknown, plaintext: Uint8Array): { ciphertext: Uint8Array; header: unknown; nextState: unknown };
  decrypt(state: unknown, ciphertext: Uint8Array, header: unknown): { plaintext: Uint8Array; nextState: unknown };
};
